/*
 * STERPBRG.C - COMMAREA bridge between the STERP Windows client and the
 * COBOL transaction engine (STERPCOB.DLL).
 *
 * Emulates the CICS "EXEC CICS LINK PROGRAM(x) COMMAREA(y)" contract that
 * the original 3270 front end used: the caller passes an 8 character
 * program name and a fixed layout communication area; the COBOL program
 * updates the area in place and GOBACKs.
 *
 * The program directory (sterpdir.h) is GENERATED by build\build-cobol.ps1
 * from the PROGRAM-ID of every module in cobol\online.  Do not edit it.
 *
 * Change log
 *   2004-02-17  KMP  Initial version for the VB6 client (STERP 3.0)
 *   2011-08-08  ANW  .NET client - cdecl exports, sterp_init
 *   2026-10-04  STERP  Program directory generated at build time
 *   2026-10-05  STERP  Pre-load this module so engine programs can resolve
 *                      user-defined COBOL FUNCTIONs (see sterp_preload)
 */
#include <windows.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <libcob.h>

typedef int (*cobprog)(unsigned char *);

#include "sterpdir.h"   /* extern declarations + static PROGDIR[] table */

static int  inited = 0;
static char lastprog[16] = "";

/*
 * GnuCOBOL resolves user-defined FUNCTIONs (FUNCTION-ID, e.g. ROUND-AWAY in
 * cobol\online\common\STFUNCS.cob) at run time through cob_resolve_func, even
 * when everything is compiled with -fstatic-call.  That lookup searches the
 * symbol table of the host EXE - which is the .NET client, not this DLL - so
 * without help it fails with "user-defined FUNCTION 'ROUND__AWAY' not found".
 *
 * Adding this module's own directory to COB_LIBRARY_PATH and naming it in
 * COB_PRE_LOAD makes libcob open STERPCOB.dll (already loaded, so this only
 * takes a reference) and search its exports, which MinGW publishes.  Must run
 * before cob_init.  Statically linked batch and test EXEs do not need this:
 * build-cobol.ps1 puts the FUNCTION objects straight on their link line.
 */
static void sterp_preload(void)
{
    char dir[MAX_PATH];
    char buf[MAX_PATH + 64];
    char *p;
    const char *old;
    HMODULE me;

    me = GetModuleHandleA("STERPCOB.dll");
    if (me == NULL) return;
    if (GetModuleFileNameA(me, dir, sizeof dir) == 0) return;
    p = strrchr(dir, '\\');
    if (p == NULL) return;
    *p = 0;
    old = getenv("COB_LIBRARY_PATH");
    if (old != NULL && *old)
        _snprintf(buf, sizeof buf - 1, "COB_LIBRARY_PATH=%s;%s", dir, old);
    else
        _snprintf(buf, sizeof buf - 1, "COB_LIBRARY_PATH=%s", dir);
    buf[sizeof buf - 1] = 0;
    _putenv(buf);
    old = getenv("COB_PRE_LOAD");
    if (old != NULL && *old && strstr(old, "STERPCOB") == NULL)
        _snprintf(buf, sizeof buf - 1, "COB_PRE_LOAD=STERPCOB;%s", old);
    else if (old == NULL || *old == 0)
        _snprintf(buf, sizeof buf - 1, "COB_PRE_LOAD=STERPCOB");
    else
        return;
    buf[sizeof buf - 1] = 0;
    _putenv(buf);
}

/* initialise COBOL runtime; odbc = connection string for SQLIO (may be NULL) */
__declspec(dllexport) int sterp_init(const char *odbc, const char *rundir)
{
    char buf[1200];
    if (odbc != NULL && *odbc) {
        _snprintf(buf, sizeof buf - 1, "STERP_ODBC=%s", odbc);
        buf[sizeof buf - 1] = 0;
        _putenv(buf);
    }
    if (rundir != NULL && *rundir) {
        _snprintf(buf, sizeof buf - 1, "STERP_RUN=%s", rundir);
        buf[sizeof buf - 1] = 0;
        _putenv(buf);
    }
    if (!inited) {
        sterp_preload();
        cob_init(0, NULL);
        inited = 1;
    }
    return 0;
}

/* LINK to a COBOL program.  returns 0 = called, -1 = program not found */
__declspec(dllexport) int sterp_link(const char *prog, unsigned char *commarea, int len)
{
    int i;
    char name[16];
    (void)len;
    if (!inited) sterp_init(NULL, NULL);
    memset(name, 0, sizeof name);
    strncpy(name, prog, 15);
    for (i = (int)strlen(name) - 1; i >= 0 && name[i] == ' '; i--) name[i] = 0;
    _strupr(name);
    strcpy(lastprog, name);
    for (i = 0; PROGDIR[i].name != NULL; i++) {
        if (strcmp(PROGDIR[i].name, name) == 0) {
            PROGDIR[i].fn(commarea);
            return 0;
        }
    }
    return -1;
}

/* number of programs in the directory and their names (for the About box) */
__declspec(dllexport) int sterp_progcount(void)
{
    int i = 0;
    while (PROGDIR[i].name != NULL) i++;
    return i;
}

__declspec(dllexport) const char *sterp_progname(int idx)
{
    if (idx < 0 || idx >= sterp_progcount()) return "";
    return PROGDIR[idx].name;
}
